    static bool Refused(Action action,string reason){try{action();return false;}catch(InvalidOperationException e){return e.Message==reason;}}
    internal static int Run(string[] args){if(args.Length!=1)return 64;bool administrator=new System.Security.Principal.WindowsPrincipal(System.Security.Principal.WindowsIdentity.GetCurrent()).IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator);if(administrator)throw new InvalidOperationException("HOST_PROBE_MUST_REMAIN_UNELEVATED");Guid nonce;if(!Guid.TryParseExact(args[0],"N",out nonce))return 65;string root=Path.GetFullPath(Path.Combine(".tmp/verification-lpac",args[0]));if(Directory.Exists(root)||File.Exists(root))return 66;Directory.CreateDirectory(root);ownedRoot=root;using(var stream=new FileStream(Path.Combine(root,"fixture-reservation.json"),FileMode.CreateNew,FileAccess.Write))using(var writer=new StreamWriter(stream,new System.Text.UTF8Encoding(false)))writer.WriteLine(new JavaScriptSerializer().Serialize(new{utc=DateTime.UtcNow.ToString("o"),root=root,nonce=args[0],owner_sid=System.Security.Principal.WindowsIdentity.GetCurrent().User.Value,administrator=administrator,profile_created=false,application_started=false}));string input=Path.Combine(root,"input"),shadow=Path.Combine(root,"shadow-home"),aliases=Path.Combine(root,"alias-fixtures");foreach(string directory in new[]{input,shadow,aliases})Directory.CreateDirectory(directory);string file=Path.Combine(input,"regular.txt"),hard=Path.Combine(aliases,"hard.txt");File.WriteAllText(file,"SYNTHETIC-INPUT");File.WriteAllText(Path.Combine(shadow,"fake-credentials.txt"),"SYNTHETIC-ONLY-JUNCTION-CONTROL");
        var facts=new List<object>();var positive=LpacInputIdentity.ValidateFile(file);facts.Add(new{kind="regular_positive",identity=positive});if(!CreateHardLinkW(hard,file,IntPtr.Zero))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());if(!Refused(()=>LpacInputIdentity.ValidateFile(file),"INPUT_HARDLINK")||!Refused(()=>LpacInputIdentity.ValidateFile(hard),"INPUT_HARDLINK"))return 1;facts.Add(new{kind="hardlinks_refused",identity=LpacInputIdentity.Inspect(hard)});File.Delete(hard);if(LpacInputIdentity.ValidateTree(input).Length!=1)return 2;
