        string old=Path.GetFullPath(".tmp/verification-lpac-symbolic/b138f0060a5249768b420dd94a6ff798");foreach(string name in new[]{"positive-symbolic.txt","shadow-symbolic.txt"}){var identity=LpacInputIdentity.Inspect(Path.Combine(old,name));if(identity.ReparseTag!=0xA000000Cu||!Refused(()=>LpacInputIdentity.ValidateFile(identity.Path),"INPUT_REPARSE"))return 4;facts.Add(new{kind="existing_symbolic_readonly_refused",identity=identity});}
        var extended=LpacInputIdentity.Inspect(@"\\?\"+Path.Combine(shadow,"fake-credentials.txt"));if(extended.ReparseTag!=0)return 5;facts.Add(new{kind="extended_path_not_junction",identity=extended});var result=new{utc=DateTime.UtcNow.ToString("o"),root=root,profile_created=false,application_started=false,administrator=administrator,existing_acl_changed=false,facts=facts.ToArray(),inner_exit_code=0};File.WriteAllText(Path.Combine(root,"input-identity-probe.json"),new JavaScriptSerializer().Serialize(result)+"\n",new System.Text.UTF8Encoding(false));Console.WriteLine(new JavaScriptSerializer().Serialize(result));return 0;
    }
